            "kind": "p",
            "text": "Observa lo que la calculadora nunca pide: ninguna longitud del cateto opuesto, ninguna longitud del cateto adyacente, ninguna hipotenusa y ningún valor de seno, coseno o tangente. Un ángulo agudo conocido es toda la entrada porque la regla de la suma de ángulos hace el resto. La herramienta tampoco acepta radianes ni una entrada directa del ángulo [[B]]; su campo de entrada es específicamente el ángulo [[A]] en grados."
