        "h2": "Comprendre la relation entre les angles complémentaires",
        "blocks": [
          {
            "kind": "p",
            "text": "Le schéma est parfaitement prévisible. Si l'angle [[A]] augmente, l'angle [[B]] diminue exactement de la même quantité, parce que leur total est verrouillé à 90 degrés. Si [[A]] diminue, [[B]] grandit pour combler l'écart. À [[A=45^\\circ]], les deux se rejoignent au milieu, et aucun angle aigu ne peut atteindre [[0^\\circ]] ni [[90^\\circ]] dans un véritable triangle rectangle à trois sommets distincts."
          },
          {
            "kind": "p",
            "text": "Le tableau est symétrique autour de 45 degrés : les paires (10, 80), (20, 70) et (30, 60) se reflètent parce qu'échanger les angles connu et manquant revient à lire la même relation complémentaire depuis l'autre côté. Les quatre panneaux ci-dessous rendent cet échange visuel."
          }
        ],
