        "h2": "Angles complémentaires et angles supplémentaires",
        "blocks": [
          {
            "kind": "p",
            "text": "Les deux termes se ressemblent et décrivent tous deux des paires d'angles, mais ils répondent à des questions différentes."
          },
          {
            "kind": "h3",
            "text": "Angles complémentaires"
          },
          {
            "kind": "p",
            "text": "Deux angles sont complémentaires lorsque leur somme vaut [[90^\\circ]]. Les deux angles aigus d'un triangle rectangle en sont l'exemple classique : ils doivent être complémentaires parce que l'angle droit réclame déjà les 90 autres degrés du total du triangle."
          },
          {
            "kind": "h3",
            "text": "Angles supplémentaires"
          },
          {
            "kind": "p",
            "text": "Deux angles sont supplémentaires lorsque leur somme vaut [[180^\\circ]]. Une ligne droite, par exemple, peut se diviser en deux angles supplémentaires. Les paires supplémentaires ne doivent jamais être confondues avec les deux angles aigus d'un triangle rectangle, qui totalisent 90 et non 180."
          },
          {
            "kind": "p",
            "text": "La somme complète des angles du triangle vaut 180 degrés, mais les deux angles aigus réunis totalisent 90 degrés. Garder ces deux totaux séparés est la clé pour éviter l'erreur la plus fréquente de cette page."
          }
        ],
