        "steps": [],
        "listItems": [
          "<strong>Soustraire l'angle connu de 180 degrés au lieu de 90.</strong> Le total de 180 degrés inclut l'angle droit, qui est déjà fixe. Ce qui va mal : avec [[A=35^\\circ]], le calcul erroné donne 145 degrés, un angle aigu impossible. Correction : soustrayez de 90, ce qui donne [[55^\\circ]].",
          "<strong>Oublier qu'un angle vaut déjà 90 degrés.</strong> L'angle droit est facile à négliger parce qu'il ne demande aucun calcul. Ce qui va mal : traiter le triangle comme si ses trois angles étaient inconnus. Correction : rappelez-vous que l'angle droit réclame la moitié du total de 180 degrés avant de commencer.",
          "<strong>Saisir 90 degrés dans la calculatrice.</strong> L'outil attend un angle aigu strictement compris entre 0 et 90 degrés. Ce qui va mal : une saisie de 90 degrés ne laisse aucune place à un second angle aigu. Correction : saisissez uniquement l'angle aigu connu.",
          "<strong>Saisir un angle supérieur à 90 degrés.</strong> Par définition, aucun angle aigu ne dépasse 90 degrés. Ce qui va mal : la soustraction donne un résultat négatif, sans signification géométrique ici. Correction : vérifiez que la saisie est inférieure à 90 degrés.",
          "<strong>Saisir 0 degré.</strong> Un angle nul écrase le triangle en un segment de droite. Ce qui va mal : le résultat prétend un complément de 90 degrés pour une figure sans aire. Correction : utilisez uniquement des angles aigus positifs.",
          "<strong>Confondre angles complémentaires et angles supplémentaires.</strong> Les paires complémentaires totalisent 90 degrés ; les paires supplémentaires totalisent 180. Ce qui va mal : soustraire de 180 reproduit l'erreur du point 1. Correction : associez chaque mot à son total, complémentaires avec 90.",
          "<strong>Supposer que les deux angles aigus doivent être égaux.</strong> L'égalité n'existe qu'à 45 degrés chacun. Ce qui va mal : attendre une symétrie dans un triangle 20-70. Correction : laissez la soustraction décider ; la plupart des paires diffèrent.",
          "<strong>Mélanger les étiquettes d'angles A et B.</strong> La calculatrice prend [[A]] et renvoie [[B]]. Ce qui va mal : saisir le complément déjà connu comme s'il s'agissait de la donnée. Correction : étiquetez l'angle connu A avant de taper quoi que ce soit.",
          "<strong>Penser que les longueurs des côtés sont nécessaires pour ce calcul précis.</strong> Les côtés comptent pour la trigonométrie, pas pour les compléments. Ce qui va mal : rester bloqué sur un problème qui ne demande qu'une soustraction. Correction : si un angle aigu est connu, soustrayez-le de 90 et terminez.",
          "<strong>Utiliser le sinus, le cosinus ou la tangente inverse alors qu'une simple soustraction suffit.</strong> Les fonctions inverses répondent à une question plus difficile. Ce qui va mal : du travail supplémentaire et des risques d'erreur de mode. Correction : quand un angle est connu, la <a href=\"/right-triangle-angle-from-sine-calculator/\" class=\"text-primary hover:underline\">calculatrice d'angle à partir du sinus</a> et ses équivalentes sont les mauvais outils ; la soustraction est exacte et immédiate.",
          "<strong>Supposer qu'un angle physique mesuré forme automatiquement un triangle rectangle sans vérifier les directions de référence.</strong> Les coins réels sont rarement parfaits. Ce qui va mal : appliquer la règle du complément là où le coin de 90 degrés n'existe pas réellement. Correction : vérifiez que les directions de référence sont perpendiculaires avant de soustraire.",
          "<strong>Arrondir une mesure saisie inutilement avant de soustraire.</strong> Un arrondi précoce jette une précision que la saisie possédait réellement. Ce qui va mal : 68.5 arrondi à 69 donne 21 au lieu de 21.5. Correction : soustrayez avec la valeur mesurée complète, puis arrondissez le résultat à la précision de la saisie."
        ],
