    "conclusion": {
      "h2": "Trouvez tout angle manquant en toute confiance",
      "paragraphs": [
        "Le calcul de l'angle manquant est l'opération la plus simple de la géométrie du triangle rectangle : soustraire l'angle aigu connu de 90 degrés. Derrière cette soustraction se cache la règle de la somme des angles d'un triangle, qui réserve la moitié de chaque total de triangle à l'angle droit et laisse l'autre moitié à la paire complémentaire. Que l'angle connu provienne d'un chevron de toit, d'une échelle, d'un limon d'escalier ou d'un tracé, la méthode ne change jamais : confirmez l'angle droit, soustrayez de 90, puis vérifiez que les deux angles aigus totalisent 90 degrés. Gardez cette page en favori pour les moments où un angle est déjà connu et où seul son partenaire manque."
      ]
    },
    "faqs": [
      {
        "question": "Comment trouver un angle manquant dans un triangle rectangle ?",
        "answer": "Soustrayez l'angle aigu connu de 90 degrés. La formule est B = 90 - A, où A est l'angle que vous connaissez et B l'angle manquant. Par exemple, si A vaut 35 degrés, alors B = 90 - 35 = 55 degrés. Aucune longueur de côté ni fonction trigonométrique n'est nécessaire."
      },
      {
        "question": "Pourquoi les deux angles aigus totalisent-ils 90 degrés ?",
        "answer": "Tout triangle contient 180 degrés au total. Un triangle rectangle réserve 90 de ces degrés à son angle droit, ce qui laisse exactement 90 degrés à partager entre les deux angles aigus restants. C'est pourquoi A + B vaut toujours 90 degrés dans un triangle rectangle."
      },
      {
        "question": "Quelle est la formule d'un angle manquant ?",
        "answer": "La formule est B = 90 - A. Partez de la somme des angles du triangle A + B + 90 = 180, soustrayez 90 des deux côtés pour obtenir A + B = 90, puis soustrayez A des deux côtés. La forme inverse, A = 90 - B, fonctionne de la même façon quand B est l'angle connu."
      },
      {
        "question": "Que sont les angles complémentaires ?",
        "answer": "Deux angles sont complémentaires lorsque leurs mesures totalisent 90 degrés. Les paires 30 et 60, 35 et 55, et 45 et 45 sont toutes complémentaires. Dans tout triangle rectangle, les deux angles aigus sont complémentaires par définition, ce qu'exprime exactement la formule de l'angle manquant."
      },
      {
        "question": "Puis-je trouver l'angle manquant sans connaître les longueurs des côtés ?",
        "answer": "Oui. Quand un angle aigu est connu, les longueurs des côtés n'ont aucune importance pour ce calcul. La relation d'angles complémentaires dépend uniquement de la somme des angles, donc soustraire de 90 degrés donne la réponse exacte. Les longueurs des côtés ne comptent que lorsqu'aucun angle n'est encore connu."
      },
      {
        "question": "Quelle est la différence entre les angles complémentaires et les angles supplémentaires ?",
        "answer": "Les angles complémentaires totalisent 90 degrés ; les angles supplémentaires totalisent 180 degrés. Les deux angles aigus d'un triangle rectangle sont complémentaires. Une erreur fréquente consiste à soustraire l'angle connu de 180 au lieu de 90, ce qui oublie que l'angle droit représente déjà la moitié du total du triangle."
      },
      {
        "question": "Les deux angles aigus peuvent-ils être égaux ?",
        "answer": "Oui, quand chacun mesure 45 degrés. Alors 90 - 45 = 45, donc le triangle est un triangle rectangle isocèle avec deux côtés de l'angle droit égaux. C'est le seul cas où les deux angles aigus sont identiques ; dans tout autre triangle rectangle, ils diffèrent."
      },
      {
        "question": "Que se passe-t-il si l'angle connu vaut 35 degrés ?",
        "answer": "L'angle manquant vaut 90 - 35 = 55 degrés. Vous pouvez le vérifier de deux façons : 35 + 55 = 90 confirme la paire complémentaire, et 35 + 55 + 90 = 180 confirme la somme complète des angles du triangle. Les deux vérifications doivent toujours concorder."
      },
      {
        "question": "Que se passe-t-il si l'angle connu est supérieur à 45 degrés ?",
        "answer": "L'angle manquant devient inférieur à 45 degrés, parce que les deux doivent toujours totaliser 90. Par exemple, si A vaut 68 degrés, alors B = 90 - 68 = 22 degrés. À mesure que l'angle connu grandit vers 90, son complément diminue vers 0."
      },
      {
        "question": "Un angle aigu manquant peut-il valoir exactement 0 ou 90 degrés ?",
        "answer": "Pas dans un triangle rectangle ordinaire. Une saisie de 0 ou 90 degrés décrit un cas limite dégénéré sans aire triangulaire réelle, et non un triangle à trois sommets distincts. La calculatrice exige que l'angle connu soit strictement compris entre 0 et 90 degrés, et le résultat se situe toujours dans le même intervalle."
      },
      {
        "question": "Comment trouver l'angle A quand l'angle B est connu ?",
        "answer": "Utilisez la formule inverse A = 90 - B. C'est la même relation complémentaire résolue pour l'autre variable. Par exemple, si B vaut 62 degrés, alors A = 90 - 62 = 28 degrés. Notez que cette calculatrice accepte l'angle A comme saisie, alors appliquez la formule inverse à la main quand seul B est connu."
      },
      {
        "question": "Quand dois-je utiliser une calculatrice de sinus, cosinus ou tangente plutôt ?",
        "answer": "Utilisez une calculatrice trigonométrique inverse quand aucun angle n'est encore connu mais que deux longueurs de côtés le sont. La calculatrice d'angle à partir du sinus a besoin du côté opposé et de l'hypoténuse, celle à partir du cosinus a besoin du côté adjacent et de l'hypoténuse, et celle à partir de la tangente a besoin des deux côtés de l'angle droit. Dès qu'un angle aigu est connu, la calculatrice d'angle manquant termine le travail."
      }
    ],
