            "text": "Beachten Sie, wonach der Rechner nie fragt: keine gegenüberliegende Seitenlänge, keine benachbarte Seitenlänge, keine Hypotenuse und keine Sinus-, Kosinus- oder Tangenswerte. Ein bekannter spitzer Winkel ist die gesamte Eingabe, weil die Winkelsummenregel den Rest erledigt. Das Tool akzeptiert auch kein Bogenmaß und keine direkte Eingabe von Winkel [[B]]; sein Eingabefeld ist speziell für Winkel [[A]] in Grad vorgesehen."
