            "kind": "p",
            "text": "Eine gerade Rampe bildet einen Winkel von [[8^\\circ]] mit der Horizontalen. Finden Sie den Komplementärwinkel zwischen der Rampenrichtung und einer vertikalen Referenzlinie."
