            "kind": "p",
            "text": "Boden, vertikale Referenz und diagonale Wange bilden das rechtwinklige Dreieck. Das 58-Grad-Ergebnis beschreibt die Wangenausrichtung gegen die Vertikale. Es prüft weder Treppenmaße noch Bauvorschriften."
