          "<strong>Den bekannten Winkel von 180 Grad statt von 90 subtrahieren.</strong> Die 180-Grad-Summe enthält den rechten Winkel, der bereits feststeht. Was schiefgeht: Bei [[A=35^\\circ]] ergibt die falsche Rechnung 145 Grad, ein unmöglicher spitzer Winkel. Korrektur: Subtrahieren Sie von 90, das ergibt [[55^\\circ]].",
          "<strong>Vergessen, dass ein Winkel bereits 90 Grad beträgt.</strong> Der rechte Winkel wird leicht übersehen, weil er keine Berechnung braucht. Was schiefgeht: Das Dreieck wird behandelt, als wären alle drei Winkel unbekannt. Korrektur: Denken Sie daran, dass der rechte Winkel die Hälfte der 180-Grad-Summe beansprucht, bevor Sie beginnen.",
          "<strong>90 Grad in den Rechner eingeben.</strong> Das Tool erwartet einen spitzen Winkel streng zwischen 0 und 90 Grad. Was schiefgeht: Eine 90-Grad-Eingabe lässt keinen Platz für einen zweiten spitzen Winkel. Korrektur: Geben Sie nur den bekannten spitzen Winkel ein.",
          "<strong>Einen Winkel größer als 90 Grad eingeben.</strong> Kein spitzer Winkel übersteigt definitionsgemäß 90 Grad. Was schiefgeht: Die Subtraktion liefert ein negatives Ergebnis, das hier keine geometrische Bedeutung hat. Korrektur: Prüfen Sie, dass die Eingabe unter 90 Grad liegt.",
          "<strong>0 Grad eingeben.</strong> Ein Nullwinkel lässt das Dreieck zu einer Strecke zusammenfallen. Was schiefgeht: Das Ergebnis behauptet ein 90-Grad-Komplement für eine Form ohne Fläche. Korrektur: Verwenden Sie nur positive spitze Winkel.",
          "<strong>Komplementärwinkel mit Supplementärwinkeln verwechseln.</strong> Komplementärpaare ergeben zusammen 90 Grad; Supplementärpaare ergeben 180. Was schiefgeht: Die Subtraktion von 180 erzeugt den Fehler aus Punkt 1. Korrektur: Ordnen Sie das Wort der Summe zu, komplementär mit 90.",
          "<strong>Annehmen, die beiden spitzen Winkel müssten gleich sein.</strong> Gleichheit gilt nur bei je 45 Grad. Was schiefgeht: Symmetrie wird in einem 20-70-Dreieck erwartet. Korrektur: Lassen Sie die Subtraktion entscheiden; die meisten Paare unterscheiden sich.",
          "<strong>Die Winkelbezeichnungen A und B verwechseln.</strong> Der Rechner nimmt [[A]] entgegen und gibt [[B]] zurück. Was schiefgeht: Das bereits bekannte Komplement wird eingegeben, als wäre es die Eingabe. Korrektur: Bezeichnen Sie den bekannten Winkel als A, bevor Sie etwas eintippen.",
          "<strong>Denken, Seitenlängen seien für diese spezielle Berechnung erforderlich.</strong> Seiten sind für Trigonometrie wichtig, nicht für Komplemente. Was schiefgeht: Man bleibt bei einem Problem stecken, das nur Subtraktion braucht. Korrektur: Ist ein spitzer Winkel bekannt, subtrahieren Sie ihn von 90 und sind fertig.",
          "<strong>Umkehrsinus, -kosinus oder -tangens verwenden, wenn einfache Subtraktion genügt.</strong> Umkehrfunktionen beantworten eine schwierigere Frage. Was schiefgeht: Mehrarbeit und mehr Chancen für Modusfehler. Korrektur: Wenn ein Winkel bekannt ist, sind der <a href=\"/right-triangle-angle-from-sine-calculator/\" class=\"text-primary hover:underline\">Winkel-aus-Sinus-Rechner</a> und seine Geschwister die falschen Werkzeuge; Subtraktion ist exakt und sofort.",
          "<strong>Annehmen, ein gemessener physikalischer Winkel bilde automatisch ein rechtwinkliges Dreieck, ohne die Referenzrichtungen zu prüfen.</strong> Echte Ecken sind selten perfekt. Was schiefgeht: Die Komplementregel wird angewandt, wo die 90-Grad-Ecke gar nicht existiert. Korrektur: Prüfen Sie, ob die Referenzrichtungen senkrecht stehen, bevor Sie subtrahieren.",
          "<strong>Eine Eingabemessung unnötig runden, bevor subtrahiert wird.</strong> Frühes Runden wirft Genauigkeit weg, die die Eingabe tatsächlich hatte. Was schiefgeht: 68.5 auf 69 gerundet ergibt 21 statt 21.5. Korrektur: Subtrahieren Sie mit dem vollständigen gemessenen Wert und runden Sie dann das Ergebnis entsprechend der Eingabegenauigkeit."
