            "text": "La risposta, in questo caso 55 gradi, rappresenta l'altro angolo acuto dello stesso triangolo rettangolo. I due angoli funzionano sempre in coppia: conoscerne uno determina completamente l'altro. Questa calcolatrice esiste proprio per questa situazione, quando un angolo è già noto e manca solo il suo complementare. Quando invece nessun angolo è ancora noto, una <a href=\"/right-triangle-angle-from-tangent-calculator/\" class=\"text-primary hover:underline\">calcolatrice dell'angolo dalla tangente</a> o una delle sue controparti di seno e coseno ricava il primo angolo dai lati misurati."
